using System;

namespace StdbModule;

public static partial class GermanQuotes
{
    public static class WilhelmBusch
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Gehabte Schmerzen // Die hab ich gern.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Junge Hähnchen, sanft gebraten, // Dazu kann man dringend raten.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Mir ist alles einerlei. // Mit Verlaub, ich bin so frei.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Nur des Geistes Kraft allein // Schneidet in die Seele ein.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Und die Liebe per Distanz, // Kurz gesagt, mißfällt mir ganz.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Rotwein ist für alte Knaben // Eine von den besten Gaben.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Die Freude flieht auf allen Wegen - // der Ärger kommt uns gern entgegen.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Im Durchschnitt ist man kummervoll // und weiß nicht, was man machen soll.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Oh, wie beglückt ist doch der Mann, // wenn er Gedichte machen kann!", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wie wohl ist dem, der dann und wann // sich etwas Schönes dichten kann!", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Der Säugling, des Gesanges müde, // Ruht aus von seinem Klageliede.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Der Weise schweigt. // Er kennt die Gründe.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Denn gerne gibt man aus der Hand, // Den Säugling, der nicht stammverwandt.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Die Schwierigkeit ist immer klein, // man muss nur nicht verhindert sein.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Viel Wasser! Wenig Likör!", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Was im Kongreß aller Dinge beschlossen ist, das wird ja wohl auch zweckgemäß und heilsam sein.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wenn man auch als gescheiter Kerl stirbt, man weiß nie, ob man nicht als Trottel wiederauflebt.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wer Steine und Eier verpackt, soll die Steine nach unten legen.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Denn die Summe unsres Lebens // Sind die Stunden, wo wir lieben.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Musik wird oft nicht schön gefunden, // Weil sie stets mit Geräusch verbunden.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Zu große Hast macht ungeschickt.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Bei dem Duett sind stets zu sehn // Zwei Mäuler, welche offen stehn.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Dann ist freilich jeder bange, // Selbst der Affengreis entfleucht, // Wenn die lange Brillenschlange // Zischend von der Palme kreucht.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Der Künstler fühlt sich stets gekränkt, // wenn's anders kommt, als wie er denkt.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Mit Recht erscheint uns das Klavier // Wenn's schön poliert, als Zimmerzier. Ob's außerdem Genuß verschafft // Bleibt hin und wieder zweifelhaft.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Das Gute - dieser Satz steht fest - // ist stets das Böse, was man läßt.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Drum soll ein Kind die weisen Lehren // Der alten Leute hochverehren! // Die haben alles hinter sich // Und sind, gottlob! recht tugendlich!", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Es ist ein Brauch von alters her: // Wer Sorgen hat, hat auch Likör!", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "In der Kammer, still und dunkel, // Schläft die Tante bei dem Onkel.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Oh! - sprach der Jean, - es ist ein Graus! // Wie schnell ist doch das Leben aus!", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Ratsam ist und bleibt es immer // Für ein junges Frauenzimmer, // Einen Mann sich zu erwählen // Und wo möglich zu vermählen.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Und der Jude mit krummer Ferse, // Krummer Nas' und krummer Hos' // Schlängelt sich zur hohen Börse // Tiefverderbt und seelenlos.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wo der Böse nächtlich praßt, // Wo im Kreis der Liberalen // Man den Heil'gen Vater haßt.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wo kriegten wir die Kinder her, // Wenn Meister Klapperstorch nicht wär?", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Zwar man zeuget viele Kinder, // Doch man denket nichts dabei. // Und die Kinder werden Sünder, // Wenn's den Eltern einerlei.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Allein man nimmt sich nicht in acht, // Und schlupp! ist man zur Welt gebracht.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Das Trinkgeschirr, sobald es leer, // Macht keine rechte Freude mehr.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Ohne Hören, ohne Sehen // Steht der Gute sinnend da; // Und er fragt, wie das geschehen, // Und warum ihm das geschah.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Oft findet man nicht den Genuss, // den man mit Recht erwarten muss.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "So geht es mit Tabak und Rum: // Erst bist du froh, dann fällst du um.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wer nichts gebraucht, der hat genug!", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Alle Menschen, ausgenommen die Damen, spricht der Weise, sind mangelhaft.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Die Welt ist wie ein Brei. Zieht man den Löffel heraus, und wär's der größte, gleich klappt die Geschichte wieder zusammen, als wenn gar nichts passiert wäre.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Drollig! Daß im Traume selbst Schnörkel lebendig werden!", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Ein Buch ist ja keine Drehorgel, womit uns der Invalide unter dem Fenster unerbittlich die Ohren zermartert.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Ein Buch, wenn es so zugeklappt daliegt, ist ein gebundenes, schlafendes, harmloses Tierchen, welches keinem was zuleide tut. Wer es nicht aufweckte, den gähnt es nicht an; wer ihm die Nase nicht grad zwischen die Kiefern steckt, den beißt's auch nicht.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Eine kleine Betriebsstörung im Verkehr zweier Herzen kann immerhin vorkommen.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Lieber ein bissel zu gut gegessen, als wie zu erbärmlich getrunken.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wer sich keinen Punkt denken kann, der ist einfach zu faul dazu!", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wie oft im Leben wirft uns das Schicksal seinen tragischen Hut vor die Füße, und wir mögen tun, was wir wollen, Verdruss gibt's doch.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wieviel Liebes und Gutes passiert uns doch in der Jugend, worauf wir im Alter nicht mehr mit Sicherheit rechnen dürfen!", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Gar manches ist vorherbestimmt; // Das Schicksal führt ihn in Bedrängnis; // Doch wie er sich dabei benimmt, // Ist seine Schuld und nicht Verhängnis.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Denn der Mensch als Kreatur // hat von Rücksicht keine Spur.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Einszweidrei, im Sauseschritt // läuft die Zeit, wir laufen mit.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Liebe - sagt man schön und richtig, - // ist ein Ding, was äußerst wichtig.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Vater werden ist nicht schwer, Vater sein dagegen sehr.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Bald klopft vor Schmerz und bald vor Lust, // das rote Ding in meiner Brust.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Es wird mit Recht ein guter Braten // gerechnet zu den guten Taten; // und dass man ihn gehörig mache, // ist weibliche Charaktersache.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Ferne Berge seh ich glühen! // Unruhvoller Wandersinn! // Morgen will ich weiter ziehen, // Weiß der Teufel, wohin!", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Früher, da ich unerfahren und bescheidner war als heute, // Hatten meine höchste Achtung andre Leute. // Später traf ich auf der Weide außer mir noch mehr Kälber, // und nun schätz ich, sozusagen, erst mich selber.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wenn Lügen Haare wären, // wir wären rauh wie Bären // Und hätten keine Glatzen.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wer einen guten Braten macht, // hat auch ein gutes Herz.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Lass sie laufen, lass sie rennen; // Nimm was bleibt, zu deinem Teile.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Ach! reines Glück genießt doch nie, // Wer zahlen soll und weiß nicht wie!", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Denn früh belehrt ihn die Erfahrung: // sobald er schrie, bekam er Nahrung.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Froh schlägt das Herz im Reisekittel, // Vorausgesetzt, man hat die Mittel.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Hoch ist der Liebe süßer Traum, // Erhaben über Zeit und Raum.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Mit scharfem Blick, nach Kennerweise, // seh' ich zunächst mal nach dem Preise. // Und bei genauerer Betrachtung, // steigt mit dem Preise auch die Achtung.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Sei mir willkommen süßer Schlaf! // Ich bin zufrieden, weil ich brav.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "So blickt man klar, wie selten nur, // ins innre Walten der Natur.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Und wahrlich! Preis und Dank gebührt // Der Kunst, die diese Welt verziert.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Eben geht mit einem Teller // Witwe Bolte in den Keller, // Daß sie von dem Sauerkohle // Eine Portion sich hole, // Wofür sie besonders schwärmt, // Wenn er wieder aufgewärmt.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "He, heraus! du Ziegen-Böck! // Schneider, Schneider, meck, meck, meck!! – Alles konnte Böck ertragen // Ohne nur ein Wort zu sagen; // Aber wenn er dies erfuhr, // Ging’s ihm wider die Natur.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Also lautet ein Beschluß: // Daß der Mensch was lernen muß.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Denn wer böse Streiche macht, // Gibt nicht auf den Lehrer acht.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wer in Dorfe oder Stadt // Einen Onkel wohnen hat // Der sei höflich und bescheiden, // Denn das mag der Onkel leiden.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "In der schönen Osterzeit // Wenn die frommen Bäckersleut’ // Viele süße Zuckersachen // Backen und zurechtemachen // Wünschten Max und Moritz auch // Sich so etwas zum Gebrauch.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Rickeracke! Rickeracke! // Geht die Mühle mit Geknacke.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Aber hier, wie überhaupt, // Kommt es anders, als man glaubt.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wenn mir aber was nicht lieb, weg damit! ist mein Prinzip.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Denen, die der Ruhe pflegen, kommen manche ungelegen.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Der Gedanke macht ihn blass, // wenn er fragt: Was kostet das?", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wer sich freut, wenn wer betrübt, macht sich meistens unbeliebt.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Tugend will ermuntert sein, Bosheit kann man schon allein!", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Bis auf weiters das Messer blitzt, die Schweine schrein, // Man muss sie halt benutzen, // Denn jeder denkt: Wozu das Schwein, // Wenn wir es nicht verputzen? // Und jeder schmunzelt, jeder nagt // Nach Art der Kannibalen, // Bis man dereinst »Pfui Teufel!« sagt // Zum Schinken aus Westfalen.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Ein jeder Wunsch, wenn er erfüllt, // kriegt augenblicklich Junge.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Ein Narr hat Glück in Masse, // Wer klug, hat selten Schwein.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Für Ewigkeit aus dunkler Tiefe // Sprudelt der Lebensquell.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Mein Kind, es sind allhier die Dinge, // Gleichwohl, ob große, ob geringe, // Im wesentlichen so verpackt, // Dass man sie nicht wie Nüsse knackt. // Wie wolltest du dich unterwinden, // Kurzweg die Menschen zu ergründen. // Du kennst sie nur von außenwärts. // Du siehst die Weste, nicht das Herz.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Mit allen Kreaturen bin ich // In schönster Seelenharmonie. // Wir sind verwandt, ich fühl es innig, // Und eben darum lieb ich sie.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Sage nie: Dann soll's geschehen! // Öffne dir ein Hinterpförtchen // Durch »Vielleicht«, das nette Wörtchen, // Oder sag: Ich will mal sehen!", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wer leben will, der muss was tun.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wer als Wein- und Weiberhasser // Jedermann im Wege steht, // Der genieße Brot und Wasser, // Bis er endlich in sich geht.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Auch das kleinste Ding hat seine Wurzel in der Unendlichkeit, ist also nicht völlig zu ergründen.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Aus faulen Eiern werden keine Küken.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Bemüh dich nur und sei hübsch froh, der Ärger kommt schon sowieso.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Böses Weib soll man dem Teufel zum Geburtstag schenken.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Das Feinste fällt durch's Sieb.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Der Ungeduldige fährt sein Heu nass ein.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Die Bäume fahren im Frühling aus der Haut.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Der Beste muss mitunter lügen; // Zuweilen tut er's mit Vergnügen.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Der Philosoph hat wie der Hausbesitzer immer Reparaturen.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Dumme Gedanken hat jeder, nur der Weise verschweigt sie.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Dummheit, die man bei anderen sieht, wirkt meist erhebend aufs Gemüt.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Dummheit ist auch eine natürliche Begabung.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Ein Onkel, der Gutes mitbringt, Ist besser als eine Tante, die bloß Klavier spielt.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Es saust der Stock, es schwirrt die Rute. // Du sollst nicht scheinen, was du bist. // Wie schad', o Mensch, dass dir das Gute // Im Grunde so zuwider ist.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Erwischtes Laster verzeiht eher als erwischte Dummheit.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Gedanken sind nicht stets parat, man schreibt auch, wenn man keine hat.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Gewisse Dinge greift man so vergeblich mit Worten an wie Geister mit Waffen.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Jede Geburt ist Wiedergeburt.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Lästige Gedanken sind wie zudringliche Stechmücken.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Man kann sein Geld nicht schlechter anlegen, als in ungezogenen Kindern.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Mancher kann nicht aus dem Fenster hinausdenken.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Materie ist die Hartnäckigkeit der kleinsten Lebewesen.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Metaphysik und Worte! Das ist grade so, als wenn man einem die Lehre von der Erbsünde auf der Flöte vorspielte.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Mitunter sitzt die größte Seele // In eines Zahnes kleiner Höhle.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Oft ist das Denken schwer, indes // das Schreiben geht auch ohne es.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Oft trifft man wen, der Bilder malt, // viel selt'ner wen, der sie bezahlt.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Platonische Liebe kommt mir vor wie ein ewiges Zielen und Niemals-Losdrücken.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Toleranz ist gut, aber nicht gegenüber den Intoleranten.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Ungeduld hat häufig Schuld.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "»Vielleicht« ist ein schlauer Krebs, der vor- und rückwärts gehen kann.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wenn es Silvester schneit, ist Neujahr nicht weit.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wenn man es nur versucht, so geht's. Das heißt mitunter, doch nicht stets.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wer auf offener See fährt, richtet sich nach den Sternen.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wer dir sagt, er hätte noch nie gelogen, dem traue nicht, mein Sohn!", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wer hinter die Puppenbühne geht, sieht die Drähte.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wer in Glaubensfragen den Verstand befragt, kriegt unchristliche Antworten.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wie klein das ist, was einer ist, // Wenn man's an seinem Dünkle misst.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wer rudert, sieht den Grunde nicht.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wer zusieht, sieht mehr, als wer mitspielt.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Zuviel und zuwenig Vertrauen sind Nachbarskinder.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Lachen ist ein Ausdruck relativer Behaglichkeit. Der Franzel hinterm Ofen freut sich der Wärme um so mehr, wenn er sieht wie sich draußen der Hansel in die rötlichen Hände pustet.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Ach, die Welt ist so geräumig, // Und der Kopf ist so beschränkt!", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Der Ruhm, wie alle Schwindelware, // Hält selten über tausend Jahre. // Zumeist vergeht schon etwas eh'r // Die Haltbarkeit und die Kulör.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Die Welt, obgleich sie wunderlich, // Ist mehr als gut genug für mich!", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Ein jeder kriegt, ein jeder nimmt // In dieser Welt, was ihm bestimmt.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Es saust der Stock, es schwirrt die Rute. // Du darfst nicht zeigen, was du bist. // Wie schad, o Mensch, dass dir das Gute // Im Grunde so zuwider ist.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Geld gehört zum Ehestande, // Häßlichkeit ist keine Schande, // Liebe ist beinah Absurdität.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Hinter jedem neuen Hügel // Dehnt sich die Unendlichkeit.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Ich bin ein armer Schreiber nur, // Hab weder Haus noch Acker, // Doch freut mich jede Kreatur, // Sogar der Spatz, der Racker.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Nur wenn ein kleines Mißgeschick // Betrifft den Treiber und Leiter, // Dann fühlt man für den Augenblick // Sich sehr befriedigt und heiter.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Und wie das häufig so der Brauch, // Der Stolz wuchs mit dem Bauche auch.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wer einsam ist, der hat es gut, // Weil keiner da, der ihm was tut.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Das weiß ein jeder, wer's auch sei, // gesund und stärkend ist das Ei.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Die erste Pflicht der Musensöhne // Ist, daß man sich ans Bier gewöhne.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Drei Wochen war der Frosch so krank! // Jetzt raucht er wieder. Gott sei Dank!", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Ehre dem Photographen! Denn er kann nichts dafür!", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Ein jeder Narr tut, was er will. // Na, meinetwegen! Ich schweige still.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Erquicklich ist die Mittagsruh, // Nur kommt man oftmals nicht dazu.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "So ist nun mal die Zeit allhie, // Erst trägt sie dich, // Dann trägst du sie; // Und wann's vorüber, weißt du nie.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Über diese Antwort des Kandidaten Jobses, // geschah allgemeines Schütteln des Kopfes.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wenn einer, der mit Mühe kaum // Gekrochen ist auf einen Baum, // Schon meint, daß er ein Vogel wär, // So irrt sich der.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Wer liebt z. B. auf dieser Erde, // Ich will mal sagen, die Steuerbehörde?", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Auch der allergewöhnlichste Gegenstand, // In Licht und Gegenlicht, // Ist wert der Betrachtung.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Darf der Gebildete nicht mehr unbefangen übers Wetter reden?", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Das hochfliegende Wort Freiheit bedeutet hienieden, förcht ich, immer weniger, je mehr mans sich ansieht.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Das Schreiben, das Schreiben, // Soll man nicht übertreiben, // Das kostet bloß Papier.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Die Thätigkeit des Blumenkohl-ähnlichen Gehirns pflegt man Geist zu nennen.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Eigentlich hat's ja nicht viel auf sich mit dem besten Pessimismus. An dem Glücklichen gleitet er ab, wie Wasser an der pomadisirten Ente, und der Unglückliche weiß ohne weiters Bescheid.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Gehör ich doch zu den Narren, die nach inwendig gucken, wo bekanntermaßen nur spärlich beleuchtet wird.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Gewißheit giebt allein die Mathematik. Aber leider streift sie nur den Oberrock der Dinge.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Im allgemeinen sei der Mensch mehr geneigt, die Sünden Anderer zu beichten, als seine eigenen.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Obgleich die Welt ja, sozusagen, // wohl manchmal etwas mangelhaft, // wird sie doch in den nächsten Tagen // vermutlich noch nicht abgeschafft.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Sie ist bekanntlich eine Hypothese der Vernunft, hat hinten und vorn ein langes Ende und in der Mitte einen tüchtigen Knoten. Es ist was für Einen der an Gehirngymnastik Vergnügen findet.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "So ein Menschenschädel hat seine aparten Winkel.", Author = "Wilhelm Busch" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Busch", Text = "Zuweilen, doch nicht so herzlich, lacht man über sich selber, sofern man sich mal bei einer mäßigen Dummheit erwischt, indem man sich nun sogar noch gescheiter vorkommt, als man selbst.", Author = "Wilhelm Busch" },
        };
    }
}
